-- ① 이름 있는 클래스

class OrderItemTemplate extends AbstractTemplate<Void> {
    private final OrderRepository repository;
    private final String itemId;

    OrderItemTemplate(LogTrace trace, OrderRepository repository, String itemId) {
        super(trace);
        this.repository = repository;
        this.itemId = itemId;
    }

    @Override protected Void call() { repository.save(itemId); return null; }
}

public void orderItem(String itemId) {
    new OrderItemTemplate(trace, orderRepository, itemId)
        .execute("OrderService.orderItem()");
}

